channel.script:
const SHEET_ID = "1t_my2HdNcRqoLrWk1LJQLbZrMLvLMOtqKeZfQyRiiNE";
const POSTS_SHEET = "MSSB_Post";

fetch(`https://opensheet.elk.sh/${SHEET_ID}/${POSTS_SHEET}`)
  .then(res => res.json())
  .then(data => {
    let rssItems = "";
    data.forEach(post => {
      rssItems += `


          ${post.Title}
          ${post.Link}
          ${post.Description || ''}
          ${new Date().toUTCString()}
          ${post.Link}
        `;
    });
    document.write(rssItems);
  })
  .catch(err => console.error(err));
